#!/usr/bin/env node
// Builds every plugins/<Name>/web/index.ts(x) into a standalone runtime bundle:
//   dist/plugin-ui/<Name>/{ui.js, ui.css, ui.json}
// `react`, `react/jsx-runtime` and `~/plugin-sdk` are NOT bundled: they become
// bindings to globalThis.__LED_MATRIX_SDK__ (see src/core/pluginSdk.ts), so the
// plugin shares the host's React and design system. lucide-react icons are
// bundled into the plugin. CSS is generated by Tailwind from the plugin's own
// sources, using the host's theme tokens (utilities only, no base reset).
import { existsSync, readdirSync, readFileSync, writeFileSync, mkdirSync, rmSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { build } from 'vite'
import postcss from 'postcss'
import tailwindcss from 'tailwindcss'

/** Bump together with UI_API_VERSION in src/core/pluginRegistry.ts. */
const UI_API_VERSION = 1

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const pluginsDir = path.resolve(root, '../plugins')
const outRoot = path.resolve(root, process.env.PLUGIN_UI_OUT ?? 'dist/plugin-ui')
const only = process.argv.slice(2)

const identifier = /^[A-Za-z_$][\w$]*$/

function sdkExportNames() {
  const src = readFileSync(path.join(root, 'src/plugin-sdk.ts'), 'utf8')
  const names = []
  for (const m of src.matchAll(/^export\s*\{([^}]*)\}/gm)) {
    for (const part of m[1].split(',')) {
      const name = part.trim().split(/\s+as\s+/).pop()
      if (name && identifier.test(name)) names.push(name)
    }
  }
  return names
}

async function hostModuleNames(id) {
  if (id === 'plugin-sdk') return sdkExportNames()
  const mod = await import(id)
  return Object.keys(mod).filter(k => identifier.test(k) && k !== 'default')
}

const externals = { 'react': 'react', 'react/jsx-runtime': 'react/jsx-runtime', '~/plugin-sdk': 'plugin-sdk' }

function sdkExternals() {
  const prefix = '\0host-sdk:'
  return {
    name: 'led-matrix-host-sdk',
    enforce: 'pre',
    resolveId(id) { if (id in externals) return prefix + externals[id] },
    async load(id) {
      if (!id.startsWith(prefix)) return
      const key = id.slice(prefix.length)
      const names = await hostModuleNames(key)
      return [
        `const m = globalThis.__LED_MATRIX_SDK__?.[${JSON.stringify(key)}]`,
        `if (!m) throw new Error('LED matrix plugin SDK is not installed')`,
        `export default m.default ?? m`,
        ...names.map(n => `export const ${n} = m.${n}`),
      ].join('\n')
    },
  }
}

function findEntry(webDir) {
  for (const f of ['index.tsx', 'index.ts']) if (existsSync(path.join(webDir, f))) return path.join(webDir, f)
}

async function buildCss(webDir, outDir) {
  // Nothing to generate (and Tailwind would warn) for plugins without any class names.
  const hasClasses = (dir) => readdirSync(dir, { withFileTypes: true, recursive: true })
    .some(e => e.isFile() && /\.(tsx?|jsx?)$/.test(e.name) && readFileSync(path.join(e.parentPath, e.name), 'utf8').includes('className'))
  if (!hasClasses(webDir)) return
  const { default: baseConfig } = await import(pathToFileURL(path.join(root, 'tailwind.config.js')).href)
  const config = { ...baseConfig, content: [path.join(webDir, '**/*.{js,ts,jsx,tsx}')] }
  const result = await postcss([tailwindcss(config)]).process('@tailwind utilities;', { from: undefined })
  if (result.css.trim()) writeFileSync(path.join(outDir, 'ui.css'), result.css)
}

const plugins = readdirSync(pluginsDir, { withFileTypes: true })
  .filter(d => d.isDirectory() && (!only.length || only.includes(d.name)))
  .map(d => ({ name: d.name, webDir: path.join(pluginsDir, d.name, 'web') }))
  .filter(p => findEntry(p.webDir))

rmSync(outRoot, { recursive: true, force: true })
for (const { name, webDir } of plugins) {
  const outDir = path.join(outRoot, name)
  mkdirSync(outDir, { recursive: true })
  await build({
    configFile: false,
    root,
    logLevel: 'warn',
    plugins: [sdkExternals()],
    esbuild: { jsx: 'automatic' },
    resolve: { alias: { 'lucide-react': path.join(root, 'node_modules/lucide-react') } },
    define: { 'process.env.NODE_ENV': '"production"' },
    build: {
      outDir, emptyOutDir: false, copyPublicDir: false, minify: true, target: 'es2022',
      lib: { entry: findEntry(webDir), formats: ['es'], fileName: () => 'ui.js' },
    },
  })
  await buildCss(webDir, outDir)
  writeFileSync(path.join(outDir, 'ui.json'), JSON.stringify({ plugin: name, api_version: UI_API_VERSION }) + '\n')
  console.log(`plugin-ui  ${name}`)
}
